package dev.cosmerearcanists.power;

import com.mojang.authlib.GameProfile;
import dev.cosmerearcanists.*;
import dev.cosmerearcanists.feruchemy.*;
import dev.cosmerearcanists.fortune.*;
import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.gametest.framework.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.effect.MobEffects;
import net.minecraft.world.entity.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.entity.ChestBlockEntity;
import net.minecraft.world.level.storage.loot.*;
import net.minecraft.world.level.storage.loot.parameters.*;
import net.minecraft.world.phys.Vec3;
import net.neoforged.neoforge.common.NeoForge;
import net.neoforged.neoforge.common.util.FakePlayer;
import net.neoforged.neoforge.gametest.*;

@GameTestHolder(CosmereArcanists.MOD_ID)
@PrefixGameTestTemplate(false)
public final class FortuneGameTests {
    private static FakePlayer player(GameTestHelper h){var p=new FakePlayer(h.getLevel(),new GameProfile(UUID.randomUUID(),"Fortunate"));p.setGameMode(GameType.SURVIVAL);p.setPos(Vec3.atCenterOf(h.absolutePos(new BlockPos(1,20,1))));PowerAttributes.set(p,"f:chromium",1);return p;}
    private static ItemStack mind(FakePlayer p,double charge){var item=new ItemStack(BuiltInRegistries.ITEM.get(ResourceLocation.fromNamespaceAndPath(CosmereArcanists.MOD_ID,"chromium_metalmind_ring")));p.setItemInHand(InteractionHand.OFF_HAND,item);if(charge>0)Metalminds.transfer(item,p.getUUID(),"chromium",charge);return item;}
    private static void update(FakePlayer p){boolean enabled=FortuneConfig.MISHAPS.get();try{FortuneConfig.MISHAPS.set(false);ChromiumFeruchemy.tick(p);}finally{FortuneConfig.MISHAPS.set(enabled);}}
    private static void tap(FakePlayer p,int level){PowerData.state(p,"f:chromium",level);update(p);}
    private static void store(FakePlayer p,int level){PowerData.state(p,"f:chromium",-level);update(p);p.getPersistentData().remove(MisfortuneService.KEY);}
    private static void close(GameTestHelper h,double a,double b,String message){h.assertTrue(Math.abs(a-b)<1e-6,message+": "+a+" != "+b);}
    private static LootParams chestParams(FakePlayer p){return new LootParams.Builder(p.serverLevel()).withParameter(LootContextParams.ORIGIN,p.position()).withParameter(LootContextParams.THIS_ENTITY,p).create(LootContextParamSets.CHEST);}
    @GameTest(template="empty") public static void fortunePaymentLevelsFishingAndLifecycleGates(GameTestHelper h){
        var p=player(h);var item=mind(p,0);PowerData.state(p,"f:chromium",-3);for(int i=0;i<20;i++)update(p);close(h,Metalminds.charge(item),.3,"Fortune storage conserves attribute-seconds");close(h,ChromiumFeruchemy.fishingLuck(p),-3,"Storing30percent gives native fishing bad luck");Metalminds.transfer(item,p.getUUID(),"chromium",100);tap(p,10);close(h,ChromiumFeruchemy.fishingLuck(p),5,"Tap10 provides five extra fishing luck");close(h,ChromiumFeruchemy.bonusAttempts(p),.5,"Tap10 has a50percent extra loot attempt chance");close(h,p.getLuck(),0,"Fortune does not leave a global Luck modifier");
        p.setItemInHand(InteractionHand.OFF_HAND,ItemStack.EMPTY);close(h,ChromiumFeruchemy.fishingLuck(p),0,"Lost contact invalidates paid output");p.setItemInHand(InteractionHand.OFF_HAND,item);PowerData.state(p,"f:chromium",0);close(h,ChromiumFeruchemy.bonusAttempts(p),0,"Off is neutral");PowerAttributes.set(p,"f:chromium",1.5);h.assertTrue(ChromiumFeruchemy.storeLevels(p)==5&&ChromiumFeruchemy.tapLevels(p)==15,"Fractional attributes determine Fortune levels");
        Metalminds.transfer(item,p.getUUID(),"chromium",-10000);Metalminds.transfer(item,p.getUUID(),"chromium",.001);tap(p,10);h.assertTrue(ChromiumFeruchemy.fishingLuck(p)>0&&ChromiumFeruchemy.fishingLuck(p)<.5,"Final fractional fuel gives proportional luck");update(p);close(h,ChromiumFeruchemy.fishingLuck(p),0,"An unfunded selector grants no luck");Metalminds.transfer(item,UUID.randomUUID(),"chromium",20);tap(p,10);close(h,ChromiumFeruchemy.fishingLuck(p),0,"Foreign owned Fortune cannot fund effects");ChromiumFeruchemy.clear(p);h.succeed();
    }
    @GameTest(template="empty") public static void nativeChestLootIsAdditiveAndAlreadyGeneratedContainersCannotReroll(GameTestHelper h){
        var p=player(h);mind(p,100);var table=p.server.reloadableRegistries().getLootTable(BuiltInLootTables.SIMPLE_DUNGEON);var params=chestParams(p);var baseline=table.getRandomItems(params,net.minecraft.util.RandomSource.create(1234));double rate=FortuneConfig.BONUS_STEP.get();try{FortuneConfig.BONUS_STEP.set(1.0);tap(p,10);var lucky=table.getRandomItems(params,net.minecraft.util.RandomSource.create(1234));h.assertTrue(lucky.size()==baseline.size()+2,"Registered GLM adds two bounded bonus stacks from the same dungeon table");for(int i=0;i<baseline.size();i++)h.assertTrue(ItemStack.matches(baseline.get(i),lucky.get(i)),"Tapping preserves every original loot stack and its components");
            var pos=h.absolutePos(new BlockPos(2,20,2));h.getLevel().setBlockAndUpdate(pos,Blocks.CHEST.defaultBlockState());var chest=(ChestBlockEntity)h.getLevel().getBlockEntity(pos);chest.setLootTable(BuiltInLootTables.SIMPLE_DUNGEON,1234);chest.unpackLootTable(p);var saved=new ArrayList<ItemStack>();for(int i=0;i<chest.getContainerSize();i++)saved.add(chest.getItem(i).copy());chest.unpackLootTable(p);h.assertTrue(chest.getLootTable()==null,"First generation consumes the chest's loot-table reference");for(int i=0;i<chest.getContainerSize();i++)h.assertTrue(ItemStack.matches(saved.get(i),chest.getItem(i)),"Reopening an already generated chest does not reroll or add loot");h.getLevel().setBlockAndUpdate(pos,Blocks.AIR.defaultBlockState());
        }finally{FortuneConfig.BONUS_STEP.set(rate);ChromiumFeruchemy.clear(p);}h.succeed();
    }
    @GameTest(template="empty") public static void fortuneMobLootUsesKillCreditAndStorageReducesLoot(GameTestHelper h){
        var p=player(h);mind(p,300);var zombie=EntityType.ZOMBIE.create(h.getLevel());var table=p.server.reloadableRegistries().getLootTable(zombie.getLootTable());var params=new LootParams.Builder(p.serverLevel()).withParameter(LootContextParams.THIS_ENTITY,zombie).withParameter(LootContextParams.ORIGIN,p.position()).withParameter(LootContextParams.DAMAGE_SOURCE,zombie.damageSources().playerAttack(p)).withParameter(LootContextParams.LAST_DAMAGE_PLAYER,p).withParameter(LootContextParams.ATTACKING_ENTITY,p).create(LootContextParamSets.ENTITY);
        double rate=FortuneConfig.BONUS_STEP.get();try{FortuneConfig.BONUS_STEP.set(1.0);int normal=0,lucky=0;for(int seed=1;seed<=24;seed++){PowerData.state(p,"f:chromium",0);normal+=table.getRandomItems(params,net.minecraft.util.RandomSource.create(seed)).stream().mapToInt(ItemStack::getCount).sum();tap(p,10);lucky+=table.getRandomItems(params,net.minecraft.util.RandomSource.create(seed)).stream().mapToInt(ItemStack::getCount).sum();}h.assertTrue(lucky>normal,"Extra native mob-table attempts improve credited drops, including chances for rare table entries");
            var context=new LootContext.Builder(params).create(Optional.empty());h.assertTrue(FortuneLootModifier.mobPlayer(context)==p,"Kill credit comes from loot params rather than nearby players");PowerAttributes.set(p,"f:chromium",4);store(p,9);int unlucky=0;for(int seed=1;seed<=24;seed++)unlucky+=table.getRandomItems(params,net.minecraft.util.RandomSource.create(seed)).stream().mapToInt(ItemStack::getCount).sum();h.assertTrue(unlucky<normal,"Heavy storage reduces native loot results");
        }finally{FortuneConfig.BONUS_STEP.set(rate);ChromiumFeruchemy.clear(p);}h.succeed();
    }
    @GameTest(template="empty") public static void misfortuneCatalogCooldownsAndDebuffGates(GameTestHelper h){
        h.assertTrue(Misfortune.values().length>=15,"At least fifteen distinct mishaps are implemented");var p=player(h);mind(p,10);store(p,1);h.assertTrue(!MisfortuneService.ready(p,Misfortune.LIGHTNING)&&MisfortuneService.ready(p,Misfortune.CRAMP),"Stronger storage is required for harsher events");h.assertTrue(MisfortuneService.apply(p,Misfortune.CRAMP)&&p.hasEffect(MobEffects.MOVEMENT_SLOWDOWN),"An eligible cramp applies a finite debuff");h.assertTrue(!MisfortuneService.apply(p,Misfortune.HUNGER_PANG),"Shared cooldown prevents stacked mishaps");PowerData.state(p,"f:chromium",0);h.assertTrue(!MisfortuneService.ready(p,Misfortune.WEAK_GRIP),"Off cannot trigger cached mishaps");store(p,3);h.assertTrue(!MisfortuneService.contextAllows(p,Misfortune.LOST_BREATH)&&!MisfortuneService.contextAllows(p,Misfortune.FIRE_FLARE),"Dry land and an unlit player prevent contextual accidents");
        boolean toggle=FortuneConfig.EVENTS.get(Misfortune.DIZZY).enabled().get();try{FortuneConfig.EVENTS.get(Misfortune.DIZZY).enabled().set(false);h.assertTrue(!MisfortuneService.apply(p,Misfortune.DIZZY),"Individual mishaps can be disabled");}finally{FortuneConfig.EVENTS.get(Misfortune.DIZZY).enabled().set(toggle);ChromiumFeruchemy.clear(p);}h.succeed();
    }
    @GameTest(template="empty") public static void contextualMisfortunesWearEquipmentAndRetainEnvironmentalRequirements(GameTestHelper h){
        var p=player(h);var metalmind=mind(p,10);store(p,3);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.IRON_PICKAXE));h.assertTrue(MisfortuneService.apply(p,Misfortune.TOOL_CHIP)&&p.getMainHandItem().getDamageValue()>0,"A tool chip uses native durability");p.getPersistentData().remove(MisfortuneService.KEY);p.setItemSlot(EquipmentSlot.HEAD,new ItemStack(Items.IRON_HELMET));h.assertTrue(MisfortuneService.apply(p,Misfortune.ARMOR_WEAR)&&p.getItemBySlot(EquipmentSlot.HEAD).getDamageValue()>0,"Armor wear uses an equipped damageable piece");
        p.getPersistentData().remove(MisfortuneService.KEY);p.setTicksFrozen(20);h.assertTrue(MisfortuneService.apply(p,Misfortune.CHILL)&&p.getTicksFrozen()>20,"A chill worsens existing freezing");p.getPersistentData().remove(MisfortuneService.KEY);p.setRemainingFireTicks(100);h.assertTrue(MisfortuneService.apply(p,Misfortune.FIRE_FLARE)&&p.getRemainingFireTicks()>100,"A flare extends existing fire");p.setRemainingFireTicks(0);p.getPersistentData().remove(MisfortuneService.KEY);h.assertTrue(!MisfortuneService.apply(p,Misfortune.FIRE_FLARE),"A fire flare cannot spontaneously ignite a dry player");
        p.setItemInHand(InteractionHand.MAIN_HAND,metalmind);p.setItemInHand(InteractionHand.OFF_HAND,new ItemStack(Items.SHIELD));p.startUsingItem(InteractionHand.OFF_HAND);h.assertTrue(MisfortuneService.apply(p,Misfortune.SHIELD_SLIP)&&!p.isUsingItem()&&p.getCooldowns().isOnCooldown(Items.SHIELD),"A shield slip interrupts an active block with a short cooldown");ChromiumFeruchemy.clear(p);h.succeed();
    }
    @GameTest(template="empty") public static void wallDetectionAndStormLightningUseLoadedWorldConditions(GameTestHelper h){
        var p=player(h);mind(p,10);store(p,3);var zombie=EntityType.ZOMBIE.create(h.getLevel());zombie.setPos(p.position().add(6,0,0));h.getLevel().addFreshEntity(zombie);var wall=BlockPos.containing(p.position().add(3,0,0));for(int y=0;y<3;y++)h.getLevel().setBlockAndUpdate(wall.above(y),Blocks.STONE.defaultBlockState());h.assertTrue(MisfortuneService.apply(p,Misfortune.WALL_DETECTION)&&zombie.getTarget()==p,"A loaded hostile can acquire the storing player through a wall");for(int y=0;y<3;y++)h.getLevel().setBlockAndUpdate(wall.above(y),Blocks.AIR.defaultBlockState());zombie.discard();p.getPersistentData().remove(MisfortuneService.KEY);
        var level=h.getLevel();boolean raining=level.isRaining(),thundering=level.isThundering();float rain=level.getRainLevel(1),thunder=level.getThunderLevel(1);var roof=p.blockPosition().above(3);var previous=level.getBlockState(roof);try{level.setWeatherParameters(0,200,true,true);level.setRainLevel(1);level.setThunderLevel(1);level.setBlockAndUpdate(roof,Blocks.STONE.defaultBlockState());h.assertTrue(!MisfortuneService.apply(p,Misfortune.LIGHTNING),"A roof protects against the storm mishap");level.setBlockAndUpdate(roof,Blocks.AIR.defaultBlockState());h.assertTrue(MisfortuneService.apply(p,Misfortune.LIGHTNING),"An exposed player in a real thunderstorm can attract a lightning entity");level.getEntitiesOfClass(net.minecraft.world.entity.LightningBolt.class,p.getBoundingBox().inflate(2)).forEach(Entity::discard);}finally{level.setBlockAndUpdate(roof,previous);level.setWeatherParameters(0,200,raining,thundering);level.setRainLevel(rain);level.setThunderLevel(thunder);ChromiumFeruchemy.clear(p);}h.succeed();
    }
    @GameTest(template="empty") public static void tossedItemsAndOwnedProjectilesCanVeerWithoutDuplicatingItems(GameTestHelper h){
        var p=player(h);mind(p,10);PowerAttributes.set(p,"f:chromium",4);store(p,9);double chance=FortuneConfig.ACTION_CHANCE.get();try{FortuneConfig.ACTION_CHANCE.set(1.0);p.getRandom().setSeed(0);var drop=new net.minecraft.world.entity.item.ItemEntity(h.getLevel(),p.getX(),p.getY(),p.getZ(),new ItemStack(Items.COBBLESTONE,3));drop.setDeltaMovement(1,.1,0);NeoForge.EVENT_BUS.post(new net.neoforged.neoforge.event.entity.item.ItemTossEvent(drop,p));h.assertTrue(Math.abs(drop.getDeltaMovement().z)>.1&&drop.getItem().getCount()==3,"A bad drop changes direction while preserving cargo");p.getPersistentData().remove(MisfortuneService.KEY);p.getRandom().setSeed(0);var snowball=EntityType.SNOWBALL.create(h.getLevel());snowball.setOwner(p);snowball.setPos(p.position());snowball.setDeltaMovement(1,0,0);h.getLevel().addFreshEntity(snowball);h.assertTrue(Math.abs(snowball.getDeltaMovement().z)>.1&&snowball.getPersistentData().getBoolean("cosmerearcanists_fortune_checked"),"A newly thrown projectile can veer and is marked to prevent repeated rolls");snowball.discard();}finally{FortuneConfig.ACTION_CHANCE.set(chance);ChromiumFeruchemy.clear(p);}h.succeed();
    }
    @GameTest(template="empty") public static void fortuneEnhancementAndConfigPreserveFuelAndDataLimits(GameTestHelper h){
        var p=player(h);var item=mind(p,100);PowerAttributes.set(p,"a:duralumin",1);PowerData.reserve(p,"duralumin",100);PowerData.state(p,"a:duralumin",1);EnhancementService.begin(p);double before=Metalminds.charge(item);tap(p,10);close(h,ChromiumFeruchemy.fundedLevels(p),17.5,"Low Allomantic duralumin amplifies Fortune tapping");close(h,before-Metalminds.charge(item),1.5*Math.pow(1.5,.25)/20*5,"Fortune pays the shared amplified resource cost");h.assertTrue(ChromiumFeruchemy.fishingLuck(p)>5&&ChromiumFeruchemy.bonusAttempts(p)<=4,"Amplification can exceed ordinary luck caps but not the loot-work budget");
        boolean enabled=FortuneConfig.ENABLED.get();try{FortuneConfig.ENABLED.set(false);update(p);close(h,ChromiumFeruchemy.fishingLuck(p),0,"Disabling Fortune removes current benefits");h.assertTrue(Metalminds.charge(item)>0,"Disabling never wipes stored charge");}finally{FortuneConfig.ENABLED.set(enabled);EnhancementService.clear(p);ChromiumFeruchemy.clear(p);}h.succeed();
    }
}
